62:function addDust(count=300){const geo=new THREE.BufferGeometry(),positions=new Float32Array(count*3),speeds=[];for(let i=0;i<count;i++){positions[i*3]=rand(-15,15);positions[i*3+1]=rand(.1,4.2);positions[i*3+2]=rand(-74,15);speeds.push(rand(.04,.22));}geo.setAttribute('position',new THREE.BufferAttribute(positions,3));const points=new THREE.Points(geo,new THREE.PointsMaterial({color:0xb8b7a5,size:.028,transparent:true,opacity:.38,depthWrite:false}));world.add(points);particles.push({points,speeds});}
