122:function updateObjectives(){const idx=game.called?(game.hold<=0?6:5):!game.storyDone?0:game.phase<=1?(game.keys===0?1:2):game.phase===2?3:game.power?5:4;$('#objective-text').textContent=objectives[game.lang][idx];$('#sector-name').textContent=tr(game.phase<2?'SEKTOR 01 · MEDIZIN':game.phase<3?'SEKTOR 02 · FORSCHUNG':'SEKTOR 03 · REAKTOR',game.phase<2?'SECTOR 01 · MEDICAL':game.phase<3?'SECTOR 02 · RESEARCH':'SECTOR 03 · REACTOR');$('#objective-progress').innerHTML=`KEYCARD ${String(game.keys).padStart(2,'0')} / 03 <span><i class="${game.keys>0?'filled':''}"></i><i class="${game.keys>1?'filled':''}"></i><i class="${game.keys>2?'filled':''}"></i></span>`;$('#log-list').innerHTML=objectives[game.lang].slice(0,6).map((s,i)=>`<li class="${i<game.phase?'complete':''}">${s}</li>`).join('');$('#squad-count').textContent=String(1+game.botCount).padStart(2,'0');}
123:function collectKey(i){if(game.keys>i)return;game.keys=Math.max(game.keys,i+1);game.phase=Math.max(game.phase,i+1);playTone(740,.16,'sine',.09);playTone(980,.25,'sine',.07);showToast(tr(['MED-Karte gesichert.','LAB-Karte gesichert.','REACTOR-Karte gesichert.'][i],['MED keycard secured.','LAB keycard secured.','REACTOR keycard secured.'][i]));updateObjectives();}
