158:function resetRun(){game.phase=0;game.keys=0;game.power=false;game.called=false;game.hold=0;game.elapsed=0;game.health=100;game.fear=0;game.stamina=100;game.battery=100;game.noise=0;game.enemyAlert=0;game.enemyDist=100;game.playerDown=false;game.revive=0;game.storyDone=false;game.paused=false;game.ending=false;game.damageCooldown=0;journalRead=false;player.pos.set(0,0,2.4);player.vel.set(0,0,0);player.yaw=0;player.pitch=0;flashOn=true;buildWorld();camera.position.set(0,1.66,2.4);camera.rotation.set(0,0,0);$('#game-ui').classList.add('active');$('#objective-log').classList.remove('open');$('#pause-screen').classList.remove('show');$('#ending-screen').classList.remove('show');$('#down-overlay').classList.remove('show');$('#damage-vignette').style.opacity=0;$('#fear-vignette').style.opacity=0;updateObjectives();}
159:function beginGame(){resetRun();game.mode='playing';setScreen(null);$('#intro-screen').classList.remove('visible');$('#game-ui').classList.add('active');renderer.domElement.requestPointerLock?.();showToast(tr('EINSATZ 04—17 · FUNKVERBINDUNG INSTABIL','OPERATION 04—17 · RADIO LINK UNSTABLE'),3200);lastTime=performance.now();}
160:function beginIntro(){game.mode='intro';setScreen('intro-screen');$('#intro-title').innerHTML='SOMEWHERE BELOW YOU,<br>IT IS ALREADY AWAKE.';$('#intro-text').innerHTML='The recorder clicks. A voice—hoarse, terrified—fills the dark.<br>“If the lights are dead, don\'t make a sound. It follows the noise.”';$('#intro-subtitle').textContent='';$('#intro-screen').querySelector('.intro-progress span').style.width='0';let progress=0;clearInterval(beginIntro.timer);beginIntro.timer=setInterval(()=>{progress+=2.5;$('#intro-screen').querySelector('.intro-progress span').style.width=Math.min(100,progress)+'%';if(progress>=100){clearInterval(beginIntro.timer);beginGame();}},240);}
162:function nearInteraction(){let best=null,bestD=Infinity;for(const it of interactables){if(it.used)continue;const d=player.pos.distanceTo(it.pos);if(d<it.r&&d<bestD){best=it;bestD=d;}}return best;}
163:function toggleFlashlight(){if(!game.hasFlashlight||game.battery<=0){showToast(tr('Taschenlampe ohne Ladung.','Flashlight battery depleted.'));return;}flashOn=!flashOn;flashlight.intensity=flashOn?3.1:0;flashlight.userData.fill.intensity=flashOn?.32:0;$('#equipment').innerHTML=tr(`${flashOn?'▰':'▱'} Taschenlampe <span>◉ Walkie-talkie</span>`,`${flashOn?'▰':'▱'} Flashlight <span>◉ Walkie-talkie</span>`);playTone(flashOn?420:190,.06,'square',.025);}
164:function moveAxis(axis,amount){if(!amount)return;const steps=Math.max(1,Math.ceil(Math.abs(amount)/.1)),step=amount/steps,radius=.32;for(let i=0;i<steps;i++){const next=player.pos.clone();next[axis]+=step;let blocked=false;for(const c of colliders){if(c.disabled)continue;const hx=c.w/2+radius,hz=c.d/2+radius;if(Math.abs(next.x-c.x)<hx&&Math.abs(next.z-c.z)<hz&&player.pos.y<c.h+.25){blocked=true;break;}}if(blocked)break;player.pos[axis]=next[axis];}}
165:function damage(amount){if(game.damageCooldown>0||game.playerDown||game.mode!=='playing')return;game.health=Math.max(0,game.health-amount);game.damageCooldown=1.15;$('#damage-vignette').style.opacity='.78';setTimeout(()=>$('#damage-vignette').style.opacity='0',240);playTone(58,.22,'sawtooth',.1);if(game.health<=0){game.playerDown=true;$('#down-overlay').classList.add('show');game.revive=0;}}
