167:function updateMonster(dt){if(!monster?.userData.active)return;monster.visible=true;const to=player.pos.clone().sub(monster.position);to.y=0;const dist=to.length();game.enemyDist=dist;game.enemyAlert=Math.max(game.enemyAlert,clamp(1-dist/22,0,1));const dir=to.normalize();const speed=game.called?1.48+Math.max(0,1-game.hold/60)*.28:1.05;monster.position.addScaledVector(dir,speed*dt);monster.rotation.y=Math.atan2(dir.x,dir.z);monster.position.y=.025+Math.sin(game.elapsed*5)*.035;if(dist<1.38)damage(game.called?22:14);monsterLight.intensity=1.1+Math.sin(game.elapsed*9)*.35;}
168:function updateBots(dt){for(let i=0;i<bots.length;i++){const bot=bots[i],off=bot.userData.offset;const target=new THREE.Vector3(player.pos.x+off.x,0,player.pos.z+off.z);const delta=target.sub(bot.position);delta.y=0;const d=delta.length();if(d>1.3){delta.normalize();bot.position.addScaledVector(delta,Math.min(d-1.1,2.25*dt));bot.rotation.y=Math.atan2(delta.x,delta.z);}}}
169:function updateHud(dt){const battery=$('#battery-meter');if(battery){battery.querySelector('b').textContent=`${Math.ceil(game.battery)}%`;battery.querySelector('i').style.width=`${game.battery}%`;battery.classList.toggle('low',game.battery<20);}$('#fear-vignette').style.opacity=String(clamp(game.fear/150,0,.72));if(game.called&&game.hold>0){$('#objective-text').textContent=`${objectives[game.lang][5]}  ·  ${Math.ceil(game.hold)}s`;}if(game.playerDown){game.revive+=dt*(bots.length?1/7:0);$('#down-overlay .revive-meter i').style.width=`${clamp(game.revive*100,0,100)}%`;if(game.revive>=1){game.playerDown=false;game.health=35;$('#down-overlay').classList.remove('show');showToast(tr('Dein Team hat dich stabilisiert.','Your team stabilized you.'));}}}
170:function update(dt){game.elapsed+=dt;game.damageCooldown=Math.max(0,game.damageCooldown-dt);if(game.called&&game.hold>0){game.hold=Math.max(0,game.hold-dt);if(game.hold===0){updateObjectives();showToast(tr('Aufzug bereit. Erreiche das Bedienfeld!','Elevator ready. Reach the control panel!'),3600);}}if(!game.paused&&!game.playerDown){const forward=(keysDown.has('KeyW')||keysDown.has('ArrowUp')?1:0)-(keysDown.has('KeyS')||keysDown.has('ArrowDown')?1:0);const side=(keysDown.has('KeyD')||keysDown.has('ArrowRight')?1:0)-(keysDown.has('KeyA')||keysDown.has('ArrowLeft')?1:0);const moving=forward!==0||side!==0;const sprint=moving&&(keysDown.has('ShiftLeft')||keysDown.has('ShiftRight'))&&game.stamina>2;const speed=sprint?5.15:3.05;if(sprint)game.stamina=Math.max(0,game.stamina-24*dt);else game.stamina=Math.min(100,game.stamina+15*dt);const f=new THREE.Vector3(Math.sin(player.yaw),0,-Math.cos(player.yaw)),r=new THREE.Vector3(Math.cos(player.yaw),0,Math.sin(player.yaw));const v=f.multiplyScalar(forward).add(r.multiplyScalar(side));if(v.lengthSq()>0)v.normalize().multiplyScalar(speed*dt);moveAxis('x',v.x);moveAxis('z',v.z);if(moving){bob+=dt*(sprint?11:7);footstep-=dt;if(footstep<=0){footstep=sprint?.28:.48;playTone(sprint?78:95,.035,'triangle',sprint?.045:.018);game.noise=sprint?1:.4;}}else game.noise=Math.max(0,game.noise-dt);camera.position.set(player.pos.x,1.66+Math.sin(bob)*.025,player.pos.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');if(flashOn&&game.battery>0){game.battery=Math.max(0,game.battery-(.22+(sprint?.28:0))*dt);if(game.battery===0){flashOn=false;flashlight.intensity=0;flashlight.userData.fill.intensity=0;showToast(tr('Die Taschenlampe ist erloschen.','The flashlight has gone dark.'));}}}updateMonster(dt);updateBots(dt);if(monster?.userData.active){const near=clamp(1-game.enemyDist/18,0,1);game.fear=clamp(game.fear+(near*9-(1-near)*2)*dt,0,100);}else game.fear=Math.max(0,game.fear-4*dt);const current=nearInteraction();$('#interaction').classList.to