content.text:
.pause-screen{position:absolute;inset:0;display:none;align-items:center;justify-content:center;flex-direction:column;background:rgba(5,7,6,.9);text-align:center;pointer-events:auto}
.pause-screen.show{display:flex}
.pause-screen h2{font:500 34px var(--serif);letter-spacing:.09em;color:#dfd7c8}
.pause-screen h2{margin:15px 0 30px}
.pause-screen h2 span{color:#a09b8c;font-size:.65em}
.pause-screen .menu-btn{pointer-events:auto;width:300px;margin:3px}
---
.game-ui{position:fixed;z-index:6;inset:0;display:none;pointer-events:none}
.game-ui.active{display:block}
.game-ui.cinematic-bars #letterbox-top,.game-ui.cinematic-bars #letterbox-bottom{height:7vh}
---
.screen{position:fixed;inset:0;z-index:5;display:none}
.screen.visible{display:flex}
.screen#main-menu{align-items:center}
---
.ending-screen,.pause-screen{position:absolute;inset:0;display:none;align-items:center;justify-content:center;flex-direction:column;background:rgba(5,7,6,.9);text-align:center;pointer-events:auto}
.ending-screen.show,.pause-screen.show{display:flex}
.ending-screen h2,.pause-screen h2{font:500 34px var(--serif);letter-spacing:.09em;color:#dfd7c8}
.ending-screen p{font:15px var(--cond);color:#aaa99f}
.ending-screen .menu-btn{pointer-events:auto;width:300px;margin-top:25px}
.ending-screen .eyebrow{color:#c1976f}

