content.text:
obj Lies das Einsatzjournal und entriegle die Sicherheitstür.
interaction [ 'interaction show', 'EBlutiges Einsatzjournal lesen' ]
ui { active: 'game-ui active', display: 'block', pause: 'none' }

input.command:
cat >> style.css <<'EOF'
body.in-game #topline{opacity:0;pointer-events:none}
.credits-card{width:min(660px,92vw)}
.credits-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 30px;margin:26px 0 24px;padding:22px 0;border-top:1px solid rgba(180,164,132,.18);border-bottom:1px solid rgba(180,164,132,.18)}
.credits-grid small{display:block;font:9px var(--mono);letter-spacing:.2em;color:#72746a;margin-bottom:7px}
.credits-grid b{font:500 17px var(--cond);letter-spacing:.12em;color:#d3c9b4}
.pause-controls{margin-top:28px;font:10px var(--mono);letter-spacing:.14em;color:#6f7168;max-width:430px;line-height:1.8}
@media(max-width:700px){.credits-grid{grid-template-columns:1fr}.credits-card{padding-bottom:26px}}
EOF
node /tmp/opencode/csslist.mjs >/dev/null && echo CSS-OK

