import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright')
const require=createRequire(join(runtime,'package.json'))
const {chromium}=require('playwright')
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'))
process.env.DISPLAY=`:${readFileSync(join(runtime,'display'),'utf8').trim()}`
const browser=await chromium.launch({...config.browser.launchOptions})
const page=await (await browser.newContext({viewport:{width:1280,height:720}})).newPage()
page.on('pageerror',e=>console.log('PAGEERROR',e.message))
await page.goto('http://localhost:3002/?playtest=1',{waitUntil:'load'})
await page.waitForTimeout(500)
for (const lang of ['de','en']) {
  if(lang==='en') { await page.click('[data-action="settings"]'); await page.click('[data-lang="en"]'); }
  await page.click('[data-action="intro"]')
  console.log(lang,'intro',await page.evaluate(()=>({title:document.querySelector('#intro-title').innerText,text:document.querySelector('#intro-text').innerText,location:document.querySelector('#intro-screen .intro-copy .eyebrow').textContent,report:document.querySelector('#intro-screen .cinematic-top span').textContent})))
  await page.evaluate(()=>{clearInterval(window.beginIntro?.timer);__f.beginGame();__f.showJournal();})
  console.log(lang,'journal',await page.$eval('#subtitles-line',e=>e.textContent))
  await page.evaluate(()=>__f.playStoryLog())
  console.log(lang,'log',await page.$eval('#subtitles-line',e=>e.textContent))
  await page.evaluate(()=>{__f.game.mode='menu';document.querySelector('#game-ui').classList.remove('active');document.querySelector('#main-menu').classList.add('visible');})
}
await browser.close()

import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright')
const require=createRequire(join(runtime,'package.json'))
const {chromium}=require('playwright')
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'))
process.env.DISPLAY=`:${readFileSync(join(runtime,'display'),'utf8').trim()}`
const browser=await chromium.launch({...config.browser.launchOptions})
for (const lang of ['de','en']) {
  const page=await (await browser.newContext({viewport:{width:1280,height:720}})).newPage()
  page.on('pageerror',e=>console.log('PAGEERROR',e.message))
  await page.goto('http://localhost:3002/?playtest=1',{waitUntil:'load'})
  await page.waitForTimeout(300)
  await page.evaluate(lang=>{__f.game.lang=lang;__f.beginIntro()},lang)
  console.log(lang,'intro',await page.evaluate(()=>({title:document.querySelector('#intro-title').innerText,text:document.querySelector('#intro-text').innerText,location:document.querySelector('#intro-screen .intro-copy .eyebrow').textContent,report:document.querySelector('#intro-screen .cinematic-top span').textContent})))
  await page.evaluate(()=>{__f.beginGame();__f.showJournal()})
  console.log(lang,'journal',await page.$eval('#subtitles-line',e=>e.textContent))
  await page.evaluate(()=>__f.playStoryLog())
  console.log(lang,'log',await page.$eval('#subtitles-line',e=>e.textContent))
  await page.close()
}
await browser.close()

