import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync, writeFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'))
process.env.DISPLAY = `:${readFileSync(join(runtime,'display'),'utf8').trim()}`
export async function open(){
  const browser = await chromium.launch({ ...config.browser.launchOptions })
  const ctx = await browser.newContext({ viewport:{width:1280,height:720} })
  const page = await ctx.newPage()
  page.on('console', m=>{ if(m.type()!=='warning') console.log('CONSOLE',m.type(),m.text()) })
  page.on('pageerror', e=>console.log('PAGEERROR',e.message))
  await page.goto('http://localhost:3002',{waitUntil:'load'})
  await page.waitForTimeout(2000)
  const session = await ctx.newCDPSession(page)
  return {browser,page,session}
}
export async function shoot(session,file){
  const {data} = await session.send('Page.captureScreenshot',{format:'jpeg',quality:82,fromSurface:true,captureBeyondViewport:false})
  writeFileSync(file,Buffer.from(data,'base64'))
}

