import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY=`:${readFileSync(join(runtime,'display'),'utf8').trim()}`;
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1280,height:720}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://localhost:3002/?playtest=1',{waitUntil:'load'});await page.waitForTimeout(500);
await page.click('[data-action="intro"]');await page.click('#skip-intro');await page.waitForTimeout(100);
const key=async()=>{await page.evaluate(()=>document.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyE',bubbles:true})));await page.waitForTimeout(30);await page.evaluate(()=>document.dispatchEvent(new KeyboardEvent('keyup',{code:'KeyE',bubbles:true})));};
const evalf=fn=>page.evaluate(fn);
let result={};
// battery pickup: set below full and move within its radius
result.battery=await evalf(()=>{__f.game.battery=40;__f.player.pos.set(4.8,0,-16.4);return {near:__f.nearInteraction()?.label,before:__f.game.battery};});await key();result.battery.after=await evalf(()=>({battery:__f.game.battery,hidden:__f.interactables.find(i=>i.kind==='item'&&i.mesh?.position.x===4.8)?.mesh?.visible}));
// security panel first refuses without journal, then unlocks after reading journal
await evalf(()=>{__f.player.pos.set(0,0,-5.7);});await key();result.panelBlocked=await evalf(()=>({gateVisible:__f.game.doors.securityDoor.visible,storyDone:__f.game.storyDone}));
await evalf(()=>__f.showJournal());await key();result.panelUnlocked=await evalf(()=>({gateVisible:__f.game.doors.securityDoor.visible,phase:__f.game.phase}));
// MED card and access gate
await evalf(()=>__f.player.pos.set(-4,0,-19));await key();result.medCard=await evalf(()=>({keys:__f.game.keys,phase:__f.game.phase}));
await evalf(()=>__f.player.pos.set(0,0,-25.5));await key();result.medGate=await evalf(()=>({visible:__f.game.doors.medDoor.visible,phase:__f.game.phase}));
// generator gating and activation
await evalf(()=>{__f.player.pos.set(4,0,-62);__f.game.keys=2;});await key();result.generatorBlocked=await evalf(()=>({power:__f.game.power,detonation:__f.game.detonation}));
await evalf(()=>{__f.game.keys=3;});await key();result.generatorOn=await evalf(()=>({power:__f.game.power,detonation:__f.game.detonation,phase:__f.game.phase}));
// solo downed hold-to-revive progression
await evalf(()=>{__f.game.botCount=0;__f.game.playerDown=true;__f.game.health=0;__f.game.bleedout=12;document.querySelector('#down-overlay').classList.add('show');});
await page.evaluate(()=>document.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyE',bubbles:true})));await evalf(()=>__f.update(8.1));result.soloRevive=await evalf(()=>({down:__f.game.playerDown,health:__f.game.health,overlay:document.querySelector('#down-overlay').classList.contains('show')}));
await page.evaluate(()=>document.dispatchEvent(new KeyboardEvent('keyup',{code:'KeyE',bubbles:true})));
// sound toggle remains accessible and its state tracks mute
await page.click('#sound-toggle');result.sound=await page.locator('#sound-toggle').evaluate(el=>({pressed:el.getAttribute('aria-pressed'),label:el.getAttribute('aria-label'),glyph:el.textContent}));
console.log(JSON.stringify({result,errors},null,2));await browser.close();

